script.setup:
// Physarum slime mould after Sebastian Lague's Slime-Simulation
// (https://github.com/SebLague/Slime-Simulation, commit 6794cfd, GPL-3.0, Copyright Sebastian Lague).
// Ported from Unity to WebGL2:
//  - Assets/Scripts/Slime/SlimeSim.compute: the Update kernel (hash, sense, steering, move, bounce) becomes a
//    fragment shader over a float texture of agents; its trail deposit becomes a pass that draws every agent as
//    a 1-pixel point with additive blending; the Diffuse kernel (3x3 blur, decay) and UpdateColourMap are ported
//    as fullscreen passes.
//  - Assets/Scripts/Slime/Simulation.cs: spawn modes, species masks, fixed step (dt 0.02, 2 steps per fixed update).
//  - Assets/Settings/A.asset .. D.asset: the four presets, values unchanged (one extra crowded preset added here).
// Added for this scene: the pointer attracts or repels agents (a scent added to what they sense), presets cycle
// on their own, and the simulation grid follows the canvas shape.
// This port is GPL-3.0 like the original.
const gl = ctx.gl;
if (!gl.getExtension("EXT_color_buffer_float")) throw new Error("This scene needs float render targets (EXT_color_buffer_float).");

// Presets from Assets/Settings/*.asset. spawn: 0 Random, 1 Point, 2 InwardCircle, 3 RandomCircle.
// species: [moveSpeed, turnSpeed, sensorAngleSpacing (deg), sensorOffsetDst, colour]
const PRESETS = [
  // Not in the repo: three species with one shared rule, 300k agents, lighter trails.
  { name: "Tribes", numAgents: 300000, spawn: 4, trailWeight: 3, decayRate: 0.4, diffuseRate: 3, species: [
    [45, 20, 40, 25, [1.0, 0.25, 0.55]],
    [45, 20, 40, 25, [0.2, 0.75, 1.0]],
    [45, 20, 40, 25, [1.0, 0.8, 0.25]],
  ] },
  { name: "A", numAgents: 250000, spawn: 2, trailWeight: 5, decayRate: 0.2, diffuseRate: 3, species: [
    [20, 2, 30, 35, [1, 1, 1]],
  ] },
  { name: "D", numAgents: 25000, spawn: 2, trailWeight: 12, decayRate: 0.5, diffuseRate: 3, species: [
    [70, 30, 60, 20, [0.53608304, 0.062745094, 1]],
    [50, -90, 112, 30, [0.10588236, 0.6240185, 0.83137256]],
    [50, 50, 70, 30, [0.47160125, 0.8301887, 0.105731584]],
  ] },
  { name: "B", numAgents: 25000, spawn: 2, trailWeight: 8, decayRate: 0.5, diffuseRate: 3, species: [
    [50, 30, 45, 20, [1, 0.06132078, 0.1610105]],
    [50, -90, 112, 30, [0.47160125, 0.8301887, 0.105731584]],
  ] },
  { name: "C", numAgents: 250000, spawn: 1, trailWeight: 2, decayRate: 0.75, diffuseRate: 5, species: [
    [30, -3, 112, 20, [0, 1, 0.31496096]],
  ] },
];

const HEAD = `#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;
`;

// SlimeSim.compute, kernel Update.
const updateFs = HEAD + `
uniform sampler2D u_agents, u_trail;
uniform int u_texW, u_numAgents, u_numSpecies;
uniform ivec2 u_size;              // width, height of the trail map
uniform float u_dt;
uniform int u_step;
uniform vec4 u_species[3];         // moveSpeed, turnSpeed, sensorAngleDegrees, sensorOffsetDst
uniform vec4 u_pointer;            // x, y (trail pixels), radius, strength (+ attract, - repel, 0 off)
out vec4 outColor;

// Hash function www.cs.ubc.ca/~rbridson/docs/schechter-sca08-turbulence.pdf
uint hash(uint state) {
  state ^= 2747636419u;
  state *= 2654435769u;
  state ^= state >> 16;
  state *= 2654435769u;
  state ^= state >> 16;
  state *= 2654435769u;
  return state;
}
float scaleToRange01(uint state) { return float(state) / 4294967295.0; }

vec3 maskOf(int species) {
  return u_numSpecies == 1 ? vec3(1.0) : vec3(species == 0, species == 1, species == 2);
}

float sense(vec2 position, float angle, vec3 speciesMask, vec4 settings, float sensorAngleOffset) {
  float sensorAngle = angle + sensorAngleOffset;
  vec2 sensorDir = vec2(cos(sensorAngle), sin(sensorAngle));
  vec2 sensorPos = position + sensorDir * settings.w;
  int sensorCentreX = int(sensorPos.x);
  int sensorCentreY = int(sensorPos.y);
  float sum = 0.0;
  vec3 senseWeight = speciesMask * 2.0 - 1.0;
  for (int offsetX = -1; offsetX <= 1; offsetX++) {     // sensorSize is 1 in every preset
    for (int offsetY = -1; offsetY <= 1; offsetY++) {
      int sampleX = min(u_size.x - 1, max(0, sensorCentreX + offsetX));
      int sampleY = min(u_size.y - 1, max(0, sensorCentreY + offsetY));
      sum += dot(senseWeight, texelFetch(u_trail, ivec2(sampleX, sampleY), 0).rgb);
    }
  }
  // The pointer smells like a strong trail (or a repellent).
  vec2 d = sensorPos - u_pointer.xy;
  sum += u_pointer.w * exp(-dot(d, d) / (u_pointer.z * u_pointer.z));
  return sum;
}

void main() {
  ivec2 cell = ivec2(gl_FragCoord.xy);
  int idx = cell.y * u_texW + cell.x;
  vec4 agent = texelFetch(u_agents, cell, 0);
  if (idx >= u_numAgents) { outColor = agent; return; }
  int speciesIndex = int(agent.w);
  vec4 settings = u_species[speciesIndex];
  vec2 pos = agent.xy;
  float angle = agent.z;
  uint id = uint(idx);
  // hash(pos.y * width + pos.x + hash(id.x + time * 100000)), in wrapping integer math (a step counter for time).
  uint random = hash(uint(pos.y) * uint(u_size.x) + uint(pos.x) + hash(id + uint(u_step) * 2000u));

  // Steer based on sensory data
  vec3 mask = maskOf(speciesIndex);
  float sensorAngleRad = settings.z * (3.1415 / 180.0);
  float weightForward = sense(pos, angle, mask, settings, 0.0);
  float weightLeft = sense(pos, angle, mask, settings, sensorAngleRad);
  float weightRight = sense(pos, angle, mask, settings, -sensorAngleRad);
  float randomSteerStrength = scaleToRange01(random);
  float turnSpeed = settings.y * 2.0 * 3.1415;
  if (weightForward > weightLeft && weightForward > weightRight) {
    angle += 0.0;
  } else if (weightForward < weightLeft && weightForward < weightRight) {
    angle += (randomSteerStrength - 0.5) * 2.0 * turnSpeed * u_dt;
  } else if (weightRight > weightLeft) {
    angle -= randomSteerStrength * turnSpeed * u_dt;
  } else if (weightLeft > weightRight) {
    angle += randomSteerStrength * turnSpeed * u_dt;
  }

  // Update position
  vec2 direction = vec2(cos(agent.z), sin(agent.z));
  vec2 newPos = pos + direction * u_dt * settings.x;
  float deposit = 1.0;
  // Clamp position to map boundaries, and pick new random move dir if hit boundary
  if (newPos.x < 0.0 || newPos.x >= float(u_size.x) || newPos.y < 0.0 || newPos.y >= float(u_size.y)) {
    random = hash(random);
    angle = scaleToRange01(random) * 2.0 * 3.1415;
    newPos.x = min(float(u_size.x) - 1.0, max(0.0, newPos.x));
    newPos.y = min(float(u_size.y) - 1.0, max(0.0, newPos.y));
    deposit = 0.0;                 // the original skips the trail deposit on a bounce
  }
  // Keep the angle bounded so float precision holds over long runs.
  angle = mod(angle, 6.2831853);
  outColor = vec4(newPos, angle, float(speciesIndex) + (deposit > 0.5 ? 0.0 : 0.5));
}`;

// The deposit half of the Update kernel: TrailMap[coord] = min(1, old + speciesMask * trailWeight * deltaTime),
// as points blended additively (the min(1) is applied in the diffuse pass).
const depositVs = HEAD + `
uniform sampler2D u_agents;
uniform int u_texW, u_numSpecies;
uniform vec2 u_size;
uniform float u_amount;
out vec3 v_add;
void main() {
  vec4 agent = texelFetch(u_agents, ivec2(gl_VertexID % u_texW, gl_VertexID / u_texW), 0);
  int species = int(agent.w);
  vec3 mask = u_numSpecies == 1 ? vec3(1.0) : vec3(species == 0, species == 1, species == 2);
  bool bounced = fract(agent.w) > 0.25;
  v_add = mask * u_amount;
  gl_Position = bounced ? vec4(2.0, 2.0, 0.0, 1.0) : vec4((floor(agent.xy) + 0.5) / u_size * 2.0 - 1.0, 0.0, 1.0);
  gl_PointSize = 1.0;
}`;
const depositFs = HEAD + `
in vec3 v_add;
out vec4 outColor;
void main() { outColor = vec4(v_add, 0.0); }`;

// SlimeSim.compute, kernel Diffuse.
const diffuseFs = HEAD + `
uniform sampler2D u_trail;
uniform ivec2 u_size;
uniform float u_dt, u_decayRate, u_diffuseRate;
out vec4 outColor;
void main() {
  ivec2 id = ivec2(gl_FragCoord.xy);
  vec3 sum = vec3(0.0);
  vec3 originalCol = min(texelFetch(u_trail, id, 0).rgb, 1.0);
  for (int offsetX = -1; offsetX <= 1; offsetX++) {
    for (int offsetY = -1; offsetY <= 1; offsetY++) {
      int sampleX = min(u_size.x - 1, max(0, id.x + offsetX));
      int sampleY = min(u_size.y - 1, max(0, id.y + offsetY));
      sum += min(texelFetch(u_trail, ivec2(sampleX, sampleY), 0).rgb, 1.0);
    }
  }
  vec3 blurredCol = sum / 9.0;
  float diffuseWeight = clamp(u_diffuseRate * u_dt, 0.0, 1.0);
  blurredCol = originalCol * (1.0 - diffuseWeight) + blurredCol * diffuseWeight;
  outColor = vec4(max(vec3(0.0), blurredCol - u_decayRate * u_dt), 1.0);
}`;

// SlimeSim.compute, kernel UpdateColourMap, plus a soft shoulder so dense veins glow instead of clipping.
const viewFs = HEAD + `
in vec2 v_uv;
uniform sampler2D u_trail;
uniform vec3 u_colours[3];
uniform int u_numSpecies;
uniform float u_bright;
out vec4 outColor;
void main() {
  vec3 map = texture(u_trail, v_uv).rgb;
  vec3 colour = vec3(0.0);
  for (int i = 0; i < 3; i++) {
    if (i >= u_numSpecies) break;
    vec3 mask = vec3(i == 0, i == 1, i == 2);
    colour += u_colours[i] * dot(map, mask);
  }
  colour *= u_bright;
  colour = 1.0 - exp(-colour * 1.4);
  outColor = vec4(pow(colour, vec3(0.92)), 1.0);
}`;

// Rescale the trail map into a new size (when the canvas changes shape).
const copyFs = HEAD + `
in vec2 v_uv;
uniform sampler2D u_src;
out vec4 outColor;
void main() { outColor = texture(u_src, v_uv); }`;
// Rescale agent positions with it.
const rescaleFs = HEAD + `
uniform sampler2D u_agents;
uniform vec2 u_scale, u_size;
out vec4 outColor;
void main() {
  vec4 a = texelFetch(u_agents, ivec2(gl_FragCoord.xy), 0);
  outColor = vec4(clamp(a.xy * u_scale, vec2(0.0), u_size - 1.0), a.zw);
}`;

const FV = ctx.utils.FULLSCREEN_VERTEX_SHADER;
Object.assign(ctx.state, {
  PRESETS,
  update: ctx.utils.createProgram(FV, updateFs),
  deposit: ctx.utils.createProgram(depositVs, depositFs),
  diffuse: ctx.utils.createProgram(FV, diffuseFs),
  view: ctx.utils.createProgram(FV, viewFs),
  copy: ctx.utils.createProgram(FV, copyFs),
  rescale: ctx.utils.createProgram(FV, rescaleFs),
  emptyVao: gl.createVertexArray(),
  agents: null, trail: null, size: null, preset: -1, presetSince: 0, acc: 0, simTime: 0,
});

// Spawn agents as Simulation.cs Init() does.
ctx.state.spawn = (p, W, H) => {
  const texW = 512, texH = Math.ceil(p.numAgents / texW), data = new Float32Array(texW * texH * 4);
  const cx = W / 2, cy = H / 2, ns = p.species.length;
  const insideUnitCircle = () => { for (;;) { const x = Math.random() * 2 - 1, y = Math.random() * 2 - 1; if (x * x + y * y <= 1) return [x, y]; } };
  for (let i = 0; i < p.numAgents; i++) {
    let x, y, angle;
    const randomAngle = Math.random() * Math.PI * 2;
    // The original sizes circles by the map height; use the shorter side so portrait canvases fit them too.
    const m = Math.min(W, H);
    if (p.spawn === 1) { x = cx; y = cy; angle = randomAngle; }
    else if (p.spawn === 0) { x = Math.random() * W; y = Math.random() * H; angle = randomAngle; }
    else if (p.spawn === 2) { const c = insideUnitCircle(); x = cx + c[0] * m * 0.5; y = cy + c[1] * m * 0.5; angle = Math.atan2(cy - y, cx - x); }
    else if (p.spawn === 3) { const c = insideUnitCircle(); x = cx + c[0] * m * 0.15; y = cy + c[1] * m * 0.15; angle = randomAngle; }
    // 4 (added here): each species fills its own slice of a disc, heading outward, so the colours start apart.
    else { const a = ((i % ns) + Math.random()) / ns * Math.PI * 2, rr = m * 0.3 * Math.sqrt(Math.random()); x = cx + Math.cos(a) * rr; y = cy + Math.sin(a) * rr; angle = a + (Math.random() - 0.5) * 1.2; }
    const species = ns === 1 ? 0 : p.spawn === 4 ? i % ns : Math.floor(Math.random() * ns);
    data.set([x, y, angle, species], i * 4);
  }
  return { texW, texH, data };
};

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const DT = 0.02;          // Unity's fixed timestep in the original project
const CYCLE = 26;         // seconds per preset when Auto cycle is on

// The trail map follows the canvas shape at about the original's 1920×1080 cells.
const aspect = w / h, AREA = 1920 * 1080;
const W = Math.max(16, Math.round(Math.sqrt(AREA * aspect))), H = Math.max(16, Math.round(Math.sqrt(AREA / aspect)));
const trailOpts = { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.LINEAR };

const load = (index) => {
  const p = s.PRESETS[index];
  const { texW, texH, data } = s.spawn(p, W, H);
  if (!s.agents || s.agents.width !== texW || s.agents.height !== texH) {
    s.agents = ctx.utils.createPingPong(texW, texH, { internalFormat: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT, filter: gl.NEAREST });
  }
  gl.bindTexture(gl.TEXTURE_2D, s.agents.read().texture);
  gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, texW, texH, gl.RGBA, gl.FLOAT, data);
  for (const t of [s.trail.read(), s.trail.write()]) {
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  }
  s.preset = index; s.texW = texW; s.presetSince = ctx.time;
};

if (!s.trail) {
  s.trail = ctx.utils.createPingPong(W, H, trailOpts);
  s.size = [W, H];
} else if (s.size[0] !== W || s.size[1] !== H) {
  // Canvas changed shape: stretch the trails and agents into the new grid so the network carries on.
  const old = s.trail;
  s.trail = ctx.utils.createPingPong(W, H, trailOpts);
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.trail.read().framebuffer);
  gl.viewport(0, 0, W, H);
  gl.useProgram(s.copy);
  ctx.utils.bindTexture(s.copy, "u_src", old.read().texture, 0);
  ctx.utils.drawFullscreen(s.copy);
  old.dispose();
  if (s.agents) {
    gl.bindFramebuffer(gl.FRAMEBUFFER, s.agents.write().framebuffer);
    gl.viewport(0, 0, s.agents.width, s.agents.height);
    gl.useProgram(s.rescale);
    ctx.utils.bindTexture(s.rescale, "u_agents", s.agents.read().texture, 0);
    ctx.utils.drawFullscreen(s.rescale, { u_scale: [W / s.size[0], H / s.size[1]], u_size: [W, H] });
    s.agents.swap();
  }
  s.size = [W, H];
}

// Preset: the person's pick, or the next one every CYCLE seconds while Auto cycle is on.
const picked = Math.round(u.u_preset);
if (picked !== s.picked) { s.picked = picked; load(picked); }
else if (u.u_reseed) load(s.preset);
else if (u.u_auto && ctx.time - s.presetSince > CYCLE) load((s.preset + 1) % s.PRESETS.length);
const p = s.PRESETS[s.preset];
const ns = p.species.length;

// Pointer in trail-map pixels; drag to attract (or repel; right-drag / Shift flips it).
const flip = (ctx.pointer.buttons & 2) || ctx.keys.has("ShiftLeft") || ctx.keys.has("ShiftRight");
const sign = (u.u_mouse === 1 ? -1 : 1) * (flip ? -1 : 1);
const pointer = ctx.mouseDown ? [ctx.mouse[0] * W, (1 - ctx.mouse[1]) * H, Math.min(W, H) * 0.06, sign * u.u_pull * 30] : [0, 0, 1, 0];

const species = new Float32Array(12), colours = new Float32Array(9);
p.species.forEach((sp, i) => {
  species.set([sp[0] * u.u_moveSpeed, sp[1] * u.u_turnSpeed, sp[2] * u.u_sensorAngle, sp[3] * u.u_sensorOffset], i * 4);
  colours.set(sp[4], i * 3);
});

// Two fixed steps per FixedUpdate at 50 Hz, as in the project: 100 steps per second of dt = 0.02.
s.acc = Math.min(s.acc + Math.min(ctx.dt, 0.05) * 100 * u.u_simSpeed, 4);
const steps = Math.floor(s.acc);
s.acc -= steps;
const n = p.numAgents, texH = s.agents.height;
for (let i = 0; i < steps; i++) {
  s.step = (s.step || 0) + 1;
  // Update kernel: sense, steer, move.
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.agents.write().framebuffer);
  gl.viewport(0, 0, s.texW, texH);
  gl.useProgram(s.update);
  ctx.utils.bindTexture(s.update, "u_agents", s.agents.read().texture, 0);
  ctx.utils.bindTexture(s.update, "u_trail", s.trail.read().texture, 1);
  ctx.utils.drawFullscreen(s.update, {
    u_texW: s.texW, u_numAgents: n, u_numSpecies: ns, u_size: [W, H], u_dt: DT, u_step: s.step % 1000000,
    u_species: species, u_pointer: pointer,
  });
  s.agents.swap();
  // Deposit: every agent adds its species mask * trailWeight * dt where it now stands.
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.trail.read().framebuffer);
  gl.viewport(0, 0, W, H);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE);
  gl.useProgram(s.deposit);
  ctx.utils.bindTexture(s.deposit, "u_agents", s.agents.read().texture, 0);
  ctx.utils.setUniforms(s.deposit, { u_texW: s.texW, u_numSpecies: ns, u_size: [W, H], u_amount: p.trailWeight * DT });
  gl.bindVertexArray(s.emptyVao);
  gl.drawArrays(gl.POINTS, 0, n);
  gl.bindVertexArray(null);
  gl.disable(gl.BLEND);
  // Diffuse kernel: blur and decay into the other buffer.
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.trail.write().framebuffer);
  gl.useProgram(s.diffuse);
  ctx.utils.bindTexture(s.diffuse, "u_trail", s.trail.read().texture, 0);
  ctx.utils.drawFullscreen(s.diffuse, { u_size: [W, H], u_dt: DT, u_decayRate: p.decayRate * u.u_decay, u_diffuseRate: p.diffuseRate * u.u_diffuse });
  s.trail.swap();
}

// UpdateColourMap, drawn to the canvas (same shape as the trail map, so nothing stretches).
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.view);
ctx.utils.bindTexture(s.view, "u_trail", s.trail.read().texture, 0);
ctx.utils.drawFullscreen(s.view, { u_colours: colours, u_numSpecies: ns, u_bright: u.u_brightness });

ctx.publish("agents", n);
ctx.publish("preset", p.name);
ctx.publish("trail map", `${W}×${H}`);
